#!/usr/bin/env python3
"""Underline all headlines (all-caps section titles) in unpacked/word/document.xml.

Uses only the Python standard library (xml.dom.minidom) since the skill's
defusedxml-based Document library is unavailable in this environment.
"""
import xml.dom.minidom as minidom

PATH = "unpacked/word/document.xml"

# CT_RPr child order around <w:u> per ECMA-376
BEFORE_U = {
    "rStyle", "rFonts", "b", "bCs", "i", "iCs", "caps", "smallCaps", "strike",
    "dstrike", "outline", "shadow", "emboss", "imprint", "noProof", "snapToGrid",
    "vanish", "webHidden", "color", "spacing", "w", "kern", "position", "sz",
    "szCs", "highlight",
}
AFTER_U = {
    "effect", "bdr", "shd", "fitText", "vertAlign", "rtl", "cs", "em", "lang",
    "eastAsianLayout", "specVanish", "oMath",
}

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"


def local_name(tag):
    return tag.split(":")[-1]


def para_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild:
            parts.append(t.firstChild.data)
    return "".join(parts)


def is_headline(p):
    text = para_text(p).strip()
    if not text:
        return False
    if not any(c.isalpha() for c in text):
        return False
    return text == text.upper()


def add_u_to_rpr(rpr):
    """Add <w:u w:val='single'/> to an existing w:rPr element in schema order."""
    if rpr is None:
        return
    for existing in rpr.getElementsByTagName("w:u"):
        if existing.parentNode is rpr:
            return  # already underlined
    doc = rpr.ownerDocument
    u = doc.createElement("w:u")
    u.setAttribute("w:val", "single")
    insert_before = None
    insert_after = None
    for child in rpr.childNodes:
        if child.nodeType != child.ELEMENT_NODE:
            continue
        name = local_name(child.tagName)
        if name in BEFORE_U:
            insert_after = child
        elif name in AFTER_U and insert_before is None:
            insert_before = child
    if insert_before is not None:
        rpr.insertBefore(u, insert_before)
    elif insert_after is not None:
        rpr.insertBefore(u, insert_after.nextSibling)
    else:
        rpr.appendChild(u)


def ensure_run_underline(run):
    """Ensure a w:r has w:rPr with w:u; create w:rPr as first child if missing."""
    rprs = run.getElementsByTagName("w:rPr")
    rpr = None
    for candidate in rprs:
        if candidate.parentNode is run:
            rpr = candidate
            break
    if rpr is None:
        rpr = run.ownerDocument.createElement("w:rPr")
        run.insertBefore(rpr, run.firstChild)
    add_u_to_rpr(rpr)


def ensure_paragraph_mark_underline(p):
    """Ensure w:pPr/w:rPr carries w:u so the paragraph mark is underlined too."""
    pprs = p.getElementsByTagName("w:pPr")
    if not pprs:
        return
    ppr = pprs[0]
    rpr = None
    for candidate in ppr.getElementsByTagName("w:rPr"):
        if candidate.parentNode is ppr:
            rpr = candidate
            break
    if rpr is None:
        rpr = p.ownerDocument.createElement("w:rPr")
        # w:rPr in w:pPr precedes sectPr/pPrChange; otherwise append
        ref = None
        for child in ppr.childNodes:
            if child.nodeType == child.ELEMENT_NODE and local_name(child.tagName) in ("sectPr", "pPrChange"):
                ref = child
                break
        if ref is not None:
            ppr.insertBefore(rpr, ref)
        else:
            ppr.appendChild(rpr)
    add_u_to_rpr(rpr)


def condense(dom):
    """Remove whitespace-only text nodes and comments (skip w:t content)."""
    for element in dom.getElementsByTagName("*"):
        if element.tagName.endswith(":t"):
            continue
        for child in list(element.childNodes):
            if (
                child.nodeType == child.TEXT_NODE
                and child.nodeValue
                and child.nodeValue.strip() == ""
            ) or child.nodeType == child.COMMENT_NODE:
                element.removeChild(child)


with open(PATH, "r", encoding="utf-8") as f:
    raw = f.read()

# Preserve the original XML declaration exactly
decl = ""
if raw.lstrip().startswith("<?xml"):
    end = raw.find("?>")
    decl = raw[: end + 2] + "\n"

dom = minidom.parseString(raw)
headlines = []
for p in dom.getElementsByTagName("w:p"):
    if not is_headline(p):
        continue
    runs = p.getElementsByTagName("w:r")
    for run in runs:
        ensure_run_underline(run)
    ensure_paragraph_mark_underline(p)
    headlines.append(para_text(p).strip())

condense(dom)

with open(PATH, "w", encoding="utf-8") as f:
    f.write(decl + dom.documentElement.toxml())

print(f"Underlined {len(headlines)} headline(s):")
for h in headlines:
    print("  -", h)

#!/usr/bin/env python3
"""Validate quarterly_report.docx: underline coverage on headlines, intact text."""
import zipfile
import xml.dom.minidom as minidom

DOCX = "quarterly_report.docx"
ORIG_PRETTY = "unpacked_pretty/document.xml"

HEADLINES = [
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
]

with zipfile.ZipFile(DOCX) as zf:
    names = zf.namelist()
    assert len(names) == 8, f"expected 8 entries, got {names}"
    assert "word/document.xml" in names
    dom = minidom.parseString(zf.read("word/document.xml"))

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"


def para_text(p):
    return "".join(
        t.firstChild.data for t in p.getElementsByTagName("w:t") if t.firstChild
    )


def run_has_u(r):
    for rpr in r.getElementsByTagName("w:rPr"):
        if rpr.parentNode is r and rpr.getElementsByTagName("w:u"):
            return True
    return False


def para_mark_has_u(p):
    for ppr in p.getElementsByTagName("w:pPr"):
        if ppr.parentNode is p:
            for rpr in ppr.getElementsByTagName("w:rPr"):
                if rpr.parentNode is ppr and rpr.getElementsByTagName("w:u"):
                    return True
    return False


paras = dom.getElementsByTagName("w:p")
print(f"Paragraph count in final doc: {len(paras)}")

# 1) Underline coverage
underlined = {}
non_headline_with_u = []
for i, p in enumerate(paras):
    text = para_text(p).strip()
    if text in HEADLINES:
        runs = [r for r in p.getElementsByTagName("w:r")]
        all_runs = runs and all(run_has_u(r) for r in runs)
        underlined[text] = (all_runs, para_mark_has_u(p))
    else:
        for r in p.getElementsByTagName("w:r"):
            if run_has_u(r):
                non_headline_with_u.append((i, text[:40]))
        if para_mark_has_u(p):
            non_headline_with_u.append((i, text[:40] + " [para-mark]"))

print("\nHeadline underline status:")
ok = True
for h in HEADLINES:
    if h not in underlined:
        print(f"  MISSING headline paragraph: {h!r}")
        ok = False
        continue
    runs_ok, mark_ok = underlined[h]
    status = "OK" if runs_ok and mark_ok else "FAIL"
    if not (runs_ok and mark_ok):
        ok = False
    print(f"  [{status}] {h!r}  runs_underlined={runs_ok} para_mark_underlined={mark_ok}")

if non_headline_with_u:
    ok = False
    print("\nUNEXPECTED underlines outside headlines:")
    for i, t in non_headline_with_u:
        print(f"  para {i}: {t!r}")
else:
    print("\nNo underlines found outside the 7 headlines (OK).")

# 2) Text integrity vs original
orig_dom = minidom.parse(ORIG_PRETTY)
orig_paras = orig_dom.getElementsByTagName("w:p")
orig_texts = [para_text(p) for p in orig_paras]
new_texts = [para_text(p) for p in paras]
if len(orig_texts) != len(new_texts):
    ok = False
    print(f"\nParagraph count changed: original {len(orig_texts)} -> new {len(new_texts)}")
elif orig_texts == new_texts:
    print(f"\nAll {len(new_texts)} paragraph texts identical to original (OK).")
else:
    ok = False
    print("\nText differences found:")
    for i, (a, b) in enumerate(zip(orig_texts, new_texts)):
        if a != b:
            print(f"  para {i}: orig={a[:50]!r} new={b[:50]!r}")

print("\nRESULT:", "PASS" if ok else "FAIL")
raise SystemExit(0 if ok else 1)

